@dataclass(slots=True)
class SpeedMetrics:
    """Latency and throughput metrics for a single device."""
    p50_ms: float
    p90_ms: float
    p99_ms: float
    mean_ms: float
    std_ms: float
    throughput_s: float

    def as_dict(self) -> dict[str, float]:
        return asdict(self)


#| export
def _nan_speed_metrics(device: str) -> SpeedMetrics:  # device string (unused, for consistent signature)
    """Create SpeedMetrics with NaN values for failed benchmarks."""
    nan = float("nan")
    return SpeedMetrics(nan, nan, nan, nan, nan, nan)


#| export
def _stats(lat_ms: np.ndarray, batch: int) -> Mapping[str, float]:
    """Compute latency statistics from raw measurements."""
    p50, p90, p99 = np.percentile(lat_ms, [50, 90, 99])
    mean = float(lat_ms.mean())
    return {
        "p50_ms": float(p50),
        "p90_ms": float(p90),
        "p99_ms": float(p99),
        "mean_ms": mean,
        "std_ms": float(lat_ms.std(ddof=1)) if lat_ms.size > 1 else 0.0,
        "throughput_s": batch * 1000.0 / mean,
    }


#| export
def _forward_latencies(
    model: nn.Module,                         # model to benchmark
    sample: torch.Tensor,                     # input tensor (with batch dimension)
    *,
    device: str | torch.device = "cpu",       # device to run on
    warmup: int = 20,                         # warmup iterations
    steps: int = 100,                         # measurement iterations
    use_torch_timer: bool | None = None,      # force torch.utils.benchmark.Timer (default: auto)
) -> np.ndarray:
    """Collect forward-pass latencies (ms) using optimal timing for each device."""
    if use_torch_timer is None:
        use_torch_timer = torch.device(device).type == "cpu"

    with _device_ctx(device) as dev:
        _ensure_device_supported(model, dev)  # quantized ops are CPU-only; avoid SIGSEGV
        model.eval().to(dev)
        sample = sample.to(dev, non_blocking=True)

        for _ in range(warmup):
            model(sample)
        _sync(dev)

        lat: list[float] = []
        if use_torch_timer and dev.type == "cpu":
            t = Timer(stmt="model(x)", globals={"model": model, "x": sample})
            m = t.blocked_autorange(min_run_time=0.3)
            per_iter = (np.asarray(m.raw_times) / m.number_per_run) * 1e3
            lat = per_iter.tolist()
        elif dev.type == "cuda":
            start_evt, end_evt = torch.cuda.Event(True), torch.cuda.Event(True)
            for _ in range(steps):
                start_evt.record()
                model(sample)
                end_evt.record()
                _sync(dev)
                lat.append(start_evt.elapsed_time(end_evt))
        else:
            for _ in range(steps):
                t0 = time.perf_counter()
                model(sample)
                lat.append((time.perf_counter() - t0) * 1e3)
        return np.asarray(lat, dtype=np.float32)


#| export
@torch.no_grad()
def compute_speed(
    model: nn.Module,                    # model to benchmark
    sample: torch.Tensor,                # input tensor (with batch dimension)
    *,
    device: str | torch.device = "cpu",  # device to run on
    warmup: int = 20,                    # warmup iterations
    steps: int = 100,                    # measurement iterations
) -> SpeedMetrics:
    """Measure latency and throughput on a single device."""
    lat = _forward_latencies(model, sample, device=device, warmup=warmup, steps=steps)
    return SpeedMetrics(**_stats(lat, sample.size(0)))


#| export
def compute_speed_multi(
    model: nn.Module,                                      # model to benchmark
    sample: torch.Tensor,                                  # input tensor (with batch dimension)
    *,
    devices: Sequence[str | torch.device] | None = None,   # devices to benchmark (default: cpu + cuda if available)
    **kwargs,
) -> dict[str, SpeedMetrics]:
    """Measure latency/throughput on multiple devices."""
    return _run_on_devices(
        compute_speed, model, sample, devices,
        nan_factory=_nan_speed_metrics,
        metric_name="Speed",
        **kwargs
    )


#| export
def sweep_threads(
    model: nn.Module,                            # model to benchmark
    sample: torch.Tensor,                        # input tensor (with batch dimension)
    thread_counts: Sequence[int] = (1, 2, 4, 8), # thread counts to test
    *,
    warmup: int = 20,                            # warmup iterations per thread count
    steps: int = 100,                            # measurement iterations per thread count
) -> list[dict]:
    """Sweep CPU thread counts to find optimal parallelism."""
    rows = []
    for n in thread_counts:
        torch.set_num_threads(n)
        lat = _forward_latencies(model, sample, device="cpu", warmup=warmup, steps=steps, use_torch_timer=True)
        rows.append({"threads": n, **_stats(lat, sample.size(0))})
    return rows


#| export
def sweep_batch_sizes(
    model: nn.Module,                                # model to benchmark
    input_shape: Sequence[int],                      # input shape WITHOUT batch dim, e.g. (3, 224, 224)
    batch_sizes: Sequence[int] = (1, 2, 4, 8, 16, 32),  # batch sizes to test
    *,
    device: str | torch.device = "cuda",             # device to run on
    warmup: int = 20,                                # warmup iterations per batch size
    steps: int = 100,                                # measurement iterations per batch size
) -> list[dict]:
    """Sweep batch sizes to find optimal throughput."""
    rows = []
    for bs in batch_sizes:
        try:
            dummy = torch.randn(bs, *input_shape)
            lat = _forward_latencies(model, dummy, device=device, warmup=warmup, steps=steps)
            stats = _stats(lat, bs)
            rows.append({"batch_size": bs, "latency_per_sample_ms": stats["mean_ms"] / bs, **stats})
        except (RuntimeError, torch.cuda.OutOfMemoryError) as e:
            warnings.warn(f"Batch size {bs} failed (likely OOM): {e}")
            rows.append({"batch_size": bs, "mean_ms": float("nan"), "throughput_s": float("nan")})
    return rows


#| export
def sweep_latency(
    model: nn.Module,                         # model to benchmark
    shapes: Sequence[Sequence[int]],          # input shapes to test, e.g. [(1,3,224,224), (1,3,384,384)]
    *,
    device: str | torch.device = "cuda",      # device to run on
    warmup: int = 20,                         # warmup iterations per shape
    steps: int = 100,                         # measurement iterations per shape
) -> list[dict]:
    """Sweep input shapes to analyze latency vs resolution."""
    rows = []
    for shape in shapes:
        dummy = torch.empty(*shape)
        lat = _forward_latencies(model, dummy, device=device, warmup=warmup, steps=steps)
        rows.append({"shape": "×".join(map(str, shape)), **_stats(lat, shape[0])})
    return rows
